    /**
     * Get Tools Filtered by Category
     */
    public static function get_by_category( string $category ): array {
        $all = self::get_1000_tools();
        if ( empty( $category ) || 'All' === $category ) {
            return $all;
        }
        return array_values( array_filter( $all, function( $tool ) use ( $category ) {
            return strtolower( $tool['category'] ) === strtolower( $category );
        } ) );
    }

    /**
     * Generate Schema.org JSON-LD WebApplication for any Tool in 1000-Tool Suite
     */
    public static function generate_schema( array $tool ): array {
        return array(
            '@context'            => 'https://schema.org',
            '@type'               => 'WebApplication',
            'name'                => $tool['name'] . ' (' . $tool['name_bn'] . ')',
            'applicationCategory' => $tool['category'],
            'operatingSystem'     => 'All Modern Web Browsers',
            'browserRequirements' => 'Requires JavaScript. Requires HTML5.',
            'url'                 => 'https://hackersshikkhok.com/tools/' . $tool['slug'] . '/',
            'description'         => $tool['description'],
            'offers'              => array(
                '@type'         => 'Offer',
                'price'         => '0',
                'priceCurrency' => 'BDT'
            ),
            'publisher'           => array(
                '@type' => 'Organization',
                'name'  => 'HackersShikkhok',
                'url'   => 'https://hackersshikkhok.com'
            )
        );
    }
